WITH cleaned AS (SELECT id, customer_id, device, browser, started_at, country, CONCAT(country, '/', device) AS country_device, COALESCE(browser, 'N/A') AS resolved_browser FROM sessions WHERE customer_id IS NOT NULL AND country IN ('SG', 'UK', 'JP')), valid AS (SELECT id, customer_id, device, browser, country, country_device, resolved_browser, INITCAP(TRIM(country)) AS country_title FROM cleaned WHERE device IN ('desktop', 'tablet', 'mobile')), cleaned_sessions AS (SELECT id, customer_id, device, browser, country_device, resolved_browser, country_title, LENGTH(browser) AS browser_length, CONCAT(browser, '/', country) AS browser_country FROM valid WHERE browser IS NOT NULL AND device = 'tablet'), kept_keys AS (SELECT id, customer_id FROM cleaned_sessions INTERSECT SELECT id, customer_id FROM sessions WHERE browser = 'Edge'), verified AS (SELECT s.* FROM cleaned_sessions s INNER JOIN kept_keys k ON s.id = k.id AND s.customer_id = k.customer_id), eligible AS (SELECT s.* FROM verified s WHERE NOT EXISTS (SELECT 1 FROM web_events x WHERE x.session_id = s.id AND x.duration_sec BETWEEN 174 AND 202)), enriched AS (SELECT s.*, p.segment, p.city FROM eligible s INNER JOIN customers p ON s.customer_id = p.id) SELECT CASE WHEN browser_length >= 73 THEN 'LARGE' ELSE 'SMALL' END AS browser_length_tier, ROUND(SUM(browser_length) / NULLIF(COUNT(CASE WHEN city = 'London' THEN 1 END), 0), 2) AS browser_length_per_london, ROUND(AVG(browser_length), 2) AS avg_browser_length, ROUND(SUM(browser_length) / NULLIF(COUNT(CASE WHEN device = 'desktop' THEN 1 END), 0), 2) AS browser_length_per_desktop, SORT_ARRAY(COLLECT_SET(segment)) AS segment_list, PERCENTILE_APPROX(browser_length, 0.95) AS browser_length_p95 FROM enriched GROUP BY CASE WHEN browser_length >= 73 THEN 'LARGE' ELSE 'SMALL' END ORDER BY browser_length_per_london DESC NULLS LAST
